176	        else if (!attributable) this.automation.hintLimit(provider, usage);
177	      } });
178	    this.runtime = new ServiceRuntime(options.home, () => this.config, options.version, this.log,
179	      message => this.emit({ event: 'notice', level: 'warning', message }),
180	      () => [...new Set([...this.foldersByClient.values()].flat())],
181	      () => this.automation.withAccountLock('codex', () => refreshCodexNativeLogin(this.config.codex.cliPath), { waitMs: MANUAL_CHECK_WAIT_MS }));
182	    this.history = new UsageHistory(this.historyDirectory(), this.historyOptions(), this.log, this.now);
183	    this.automation.history = this.history;
184	    this.history.prune();
185	    this.log(`usage history: ${this.history.enabled ? this.history.location : 'off'}`);
186	  }
