188	  /** Keep the active native login fresh even without a saved profile or a connected editor. */
189	  private async pollUsage(): Promise<void> {
190	    if (this.disposed) return;
191	    const work: Promise<unknown>[] = PROVIDERS.map(provider => this.liveUsage(provider));
192	    for (const clientId of this.usageContexts.keys()) work.push(this.liveUsage('copilot', false, clientId));
193	    if (!this.usageContexts.size) work.push(this.liveUsage('copilot'));
194	    for (const result of await Promise.allSettled(work)) {
195	      if (result.status === 'rejected') this.log(`usage: ${String(result.reason)}`);
196	    }
197	  }
198	
199	  async liveUsage(provider: ProviderId, force = false, clientId?: number): Promise<UsageStateView> {
200	    let context = this.usageContexts.get(clientId ?? -1);
201	    if (provider === 'copilot' && !context) {
202	      const token = process.env.GH_TOKEN || process.env.GITHUB_TOKEN;
203	      context = { accounts: token ? [{ login: this.config.copilot.account || 'GitHub', token }] : [] };
204	    }
205	    if (provider !== 'copilot') await this.followNative(provider);
206	    const active = provider === 'copilot' ? undefined : this.store.activeProfileId(provider);
207	    const state = await this.usageMonitor.read(provider, force, context);
208	    if (provider !== 'copilot' && active && active === this.store.activeProfileId(provider) && await this.store.matchesNative(provider, active)) {
209	      const usage = newestValidUsage(state.lastGood, this.automation.usage(provider, active), this.now());
210	      if (usage) { state.lastGood = usage; if (state.result.kind === 'ok') state.result = { kind: 'ok', usage }; }
211	    }
212	    if (provider !== 'copilot' && active !== this.store.activeProfileId(provider)) {
213	      return serializeUsageState({ identity: (this.options.usageIdentity ?? nativeUsageIdentity)(provider), result: { kind: 'unavailable', provider, reason: 'The active account changed; waiting for its reading.' } });
214	    }
215	    return { ...serializeUsageState(state), profileId: active };
216	  }
