240	  /** A switch made by hand or followed from outside; rotation records its own switches with more detail. */
241	  private recordSwitch(provider: AuthProvider, previous: string | undefined, id: string, reason: 'manual' | 'external'): void {
242	    if (previous === id) { return; }
243	    const stayedMs = previous ? this.automation.stayed(provider, previous) : undefined;
244	    this.history.record({ type: 'switch', provider, reason, automatic: false,
245	      ...(previous ? { from: this.automation.account(provider, previous) } : {}), to: this.automation.account(provider, id),
246	      ...(stayedMs !== undefined ? { stayedMs } : {}),
247	      fromUsage: previous ? usageSnapshot(this.automation.usage(provider, previous)) : undefined,
248	      toUsage: usageSnapshot(this.automation.usage(provider, id)) });
