251	  /** Follows a native login switched outside the service and records it; returns whether the active profile changed. */
252	  private async followNative(provider: AuthProvider): Promise<boolean> {
253	    const previous = this.store.activeProfileId(provider);
254	    const changed = await this.store.followNative(provider);
255	    if (changed) {
256	      const current = this.store.activeProfileId(provider);
257	      if (current) { this.recordSwitch(provider, previous, current, 'external'); }
258	    }
259	    return changed;
