269	  /** The last `days` days, or everything kept, summarized with the rotation thresholds in effect. */
270	  historySummary(days?: number): HistorySummaryResult {
271	    const files = this.history.files();
272	    const now = this.now();
273	    const oldest = files.length ? historyFileStart(path.basename(files[0])) : undefined;
274	    const since = days ? now - days * 86_400_000 : oldest ?? now;
275	    const thresholds: Partial<Record<AuthProvider, Thresholds>> = {};
276	    for (const provider of PROVIDERS) {
277	      const settings = automationSettings(this.config, provider);
278	      thresholds[provider] = { fiveHourThresholdPercent: settings.fiveHourThresholdPercent, weeklyThresholdPercent: settings.weeklyThresholdPercent };
279	    }
280	    const summary = summarizeHistory(this.history.events(since), { since, until: now, thresholds });
281	    const label = days ? `the last ${days} days` : 'everything kept';
282	    const markdown = renderHistoryReport(summary, { label, location: this.history.location, files: files.length, retentionDays: Math.round(this.history.retentionMs / 86_400_000) });
283	    return { markdown, since: new Date(since).toISOString(), until: new Date(now).toISOString(), label, summary };
284	  }
