343	
344	  /** The lock wait a request asked for; a request with a token can be cancelled through `automation.cancel`. */
345	  private waitFor(provider: AuthProvider, params: Record<string, unknown>): LockWait & { token?: string } {
346	    const token = typeof params.token === 'string' && params.token ? params.token : undefined;
347	    const controller = new AbortController();
348	    if (token) { this.cancels.get(token)?.abort(); this.cancels.set(token, controller); }
349	    const waitMs = typeof params.waitMs === 'number' && Number.isFinite(params.waitMs) ? Math.max(0, params.waitMs) : MANUAL_CHECK_WAIT_MS;
350	    return { token, waitMs, signal: controller.signal, onWait: () => this.emit({ event: 'waiting', provider, token }) };
351	  }
352	
353	  private releaseWait(wait: { token?: string; signal?: AbortSignal }): void {
354	    if (wait.token && this.cancels.get(wait.token)?.signal === wait.signal) { this.cancels.delete(wait.token); }
355	  }
356	
357	  /** One keep-alive sweep over `profiles` under one lock, spaced, stopping on cancel or on a sign-in's hold. */
358	  private async keepAliveAll(provider: AuthProvider, profiles: ProfileMetadata[], wait: LockWait & { token?: string }): Promise<KeepAliveAllResult> {
359	    const result: KeepAliveAllResult = { results: [], done: 0, total: profiles.length, cancelled: false };
360	    const signal = wait.signal;
361	    try {
362	      await this.automation.withAccountLock(provider, async () => {
363	        for (const [index, profile] of profiles.entries()) {
364	          if (signal?.aborted) { result.cancelled = true; break; }
365	          // Space the calls so a sweep of every account does not burst the provider's usage endpoint.
366	          if (index > 0) { await sleep(KEEP_ALIVE_ALL_SPACING_MS, signal); }
367	          if (signal?.aborted) { result.cancelled = true; break; }
368	          this.emit({ event: 'keepAliveProgress', provider, token: wait.token, index, total: profiles.length, id: profile.id, name: profile.name });
369	          try {
370	            const outcome = await this.automation.sendKeepAliveNow(provider, profile.id);
371	            result.results.push({ id: profile.id, name: profile.name, ...serializeKeepAlive(outcome) });
372	          } catch (error) {
373	            const message = error instanceof Error ? error.message : String(error);
374	            // A sign-in started meanwhile holds every check of this service; the rest of the sweep would only fail the same way.
375	            if (/sign-in is in progress/i.test(message)) { result.blocked = message.replace(/\.$/, ''); break; }
376	            result.results.push({ id: profile.id, name: profile.name, error: message });
377	          }
378	          result.done++;
379	        }
380	      }, wait);
381	    } catch (error) {
382	      const message = error instanceof Error ? error.message : String(error);
383	      if (signal?.aborted) { result.cancelled = true; }
384	      else if (/already running/i.test(message)) { result.blocked = `another ${TITLES[provider]} account check was still running after ${Math.round((wait.waitMs ?? 0) / 60_000)} minutes`; }
385	      else { throw error; }
386	    }
387	    return result;
388	  }
