390	  /** One round of the periodic work: follow outside switches, sweep, retry the Claude identity sync. */
391	  async tick(): Promise<void> {
392	    if (this.disposed) { return; }
393	    this.reloadConfigIfChanged();
394	    for (const provider of PROVIDERS) {
395	      try {
396	        if (await this.followNative(provider)) { this.emit({ event: 'stateChanged', provider }); }
397	      } catch (error) { this.log(`${provider}: could not follow the native login: ${error instanceof Error ? error.message : String(error)}`); }
398	    }
399	    await this.automation.tick();
400	    await this.retryClaudeAccountMetadata();
401	    this.history.pruneIfDue();
402	    await this.runtime.sync();
403	  }
