432	  private profileView(provider: AuthProvider, profile: ProfileMetadata, number: number, active: boolean): ProfileView {
433	    const state = this.automation.accountState(provider, profile.id);
434	    const problems: ProfileView['problems'] = [];
435	    for (const [check, raw] of [['keepAlive', state.keepAliveError], ['usage', state.lastError]] as const) {
436	      if (!raw) { continue; }
437	      const problem = explainAccountProblem(raw);
438	      problems.push({ check, raw, label: problem.label, advice: problem.advice, known: problem.known });
439	    }
440	    return {
441	      ...profile, active, number,
442	      usage: this.automation.usage(provider, profile.id) ? state.usage as SerializedUsage : undefined,
443	      checkedAt: isoOrUndefined(state.checkedAt),
444	      lastKeepAliveAt: isoOrUndefined(state.lastKeepAliveAt),
445	      problems,
446	      limit: this.automation.limitState(provider, profile.id),
447	      loginProblem: this.automation.loginProblem(provider, profile.id),
448	      hasCredential: this.store.hasCredential(provider, profile.id),
449	      folder: profile.folder
