454	
455	  private async activate(provider: AuthProvider, id: string, automatic: boolean): Promise<ActivationOutcome> {
456	    const previous = this.store.activeProfileId(provider);
457	    const outcome = await this.store.activateProfile(provider, id, automatic);
458	    // Rotation records its switches itself, with the candidates it considered.
459	    if (!automatic) { this.recordSwitch(provider, previous, id, 'manual'); }
460	    this.emit({ event: 'activated', provider, id: outcome.profile.id, name: outcome.profile.name, email: outcome.profile.email, automatic,
461	      accountChanged: outcome.accountChanged, level: outcome.level, message: outcome.message });
462	    this.emit({ event: 'stateChanged', provider });
463	    return outcome;
464	  }
465	
466	  private async verifyActivation(provider: AuthProvider, credential: StoredCredential, expected: CredentialIdentity) {
467	    if (provider === 'codex') {
468	      // A fresh app-server must see the login that was just written; report a mismatch instead of success.
469	      return (this.options.verifyCodex ?? verifyCodexNativeAccount)(credential, this.config.codex.cliPath || 'codex');
470	    }
471	    // Claude Code renders /status and /usage identity from its separate account file. Keep that metadata and its
472	    // account-bound caches aligned with the exact OAuth token that activation just wrote.
473	    const outcome = await (this.options.syncClaudeMetadata ?? activateClaudeAccountMetadata)(credential, expected);
474	    if (outcome.status === 'synced') {
475	      this.claudeMetadataRetry = undefined;
476	      return { status: 'match' as const, detail: outcome.detail, ...outcome.identity };
477	    }
478	    // The identity is unconfirmed, usually because the endpoint is rate-limiting this account. Keep asking in the
479	    // background so /status and /usage stop lagging behind the switch without anyone doing anything.
480	    this.claudeMetadataRetry = { nextAttemptAt: this.now() + Math.max(outcome.retryAfterMs ?? 0, CLAUDE_METADATA_RETRY_MS), attempts: 0 };
481	    return { status: 'unverified' as const, detail: outcome.detail };
482	  }
483	
484	  /**
485	   * Retries the Claude identity sync for a switch whose profile lookup failed. The native credential is re-read every
486	   * attempt, so a token the CLI refreshed in the meantime is used, and a later switch simply retargets the retry.
487	   */
488	  private async retryClaudeAccountMetadata(): Promise<void> {
489	    const pending = this.claudeMetadataRetry;
490	    if (!pending || this.now() < pending.nextAttemptAt) { return; }
491	    const expected = this.store.activeIdentity('claude');
492	    // Claude Code refreshes its own profile after a switch; once it has, there is nothing left to correct.
493	    if (claudeAccountFileConfirms(expected)) {
494	      this.claudeMetadataRetry = undefined;
495	      this.log(`claude: account metadata already names the activated login (${expected.email ?? expected.accountId})`);
496	      return;
497	    }
498	    let credential: StoredCredential;
499	    try {
500	      credential = readNativeCredential('claude');
501	    } catch (error) {
502	      this.claudeMetadataRetry = undefined;
503	      this.log(`claude: stopped confirming the activated login, no readable native credential: ${error instanceof Error ? error.message : String(error)}`);
504	      return;
505	    }
506	    const outcome = await (this.options.syncClaudeMetadata ?? activateClaudeAccountMetadata)(credential, expected);
507	    if (outcome.status === 'synced') {
508	      this.claudeMetadataRetry = undefined;
509	      this.log(`claude: account metadata confirmed on retry — ${outcome.detail}`);
510	      return;
511	    }
512	    pending.attempts += 1;
513	    if (pending.attempts >= CLAUDE_METADATA_RETRY_LIMIT) {
514	      this.claudeMetadataRetry = undefined;
515	      this.log(`claude: gave up confirming the activated login after ${pending.attempts} attempts — ${outcome.detail}`);
516	      return;
517	    }
518	    // Back off linearly, and never sooner than the endpoint asked for.
519	    pending.nextAttemptAt = this.now() + Math.max(outcome.retryAfterMs ?? 0, CLAUDE_METADATA_RETRY_MS * Math.min(pending.attempts, 5));
520	    this.log(`claude: could not confirm the activated login (attempt ${pending.attempts}) — ${outcome.detail}`);
521	  }
