529	  /** A hand-edited config.json is picked up on the next tick. */
530	  private reloadConfigIfChanged(): void {
531	    const stamp = this.stampOfConfigFile();
532	    if (stamp === this.configStamp) { return; }
533	    this.configStamp = stamp;
534	    const next = loadConfig(this.configFile);
535	    if (JSON.stringify(next) === JSON.stringify(this.config)) { return; }
536	    this.config = next;
537	    this.log('config: reloaded config.json after it changed on disk');
538	    this.applyHistoryConfig();
539	    void this.runtime.sync();
540	    this.emit({ event: 'configChanged', config: this.config });
541	  }
