543	  /** Applies `values` (dotted keys such as `claude.autoRotate.enabled`) and saves; unchanged values emit nothing. */
544	  setConfig(values: Record<string, unknown>): ServiceConfig {
545	    let next = this.config;
546	    for (const [key, value] of Object.entries(values)) { next = setConfigValue(next, key, value); }
547	    if (JSON.stringify(next) === JSON.stringify(this.config)) { return this.config; }
548	    saveConfig(this.configFile, next);
549	    this.configStamp = this.stampOfConfigFile();
550	    const changed = Object.keys(values).filter((key) => JSON.stringify(getValue(this.config, key)) !== JSON.stringify(getValue(next, key)));
551	    this.config = next;
552	    this.log(`config: changed ${changed.map((key) => `${key} = ${JSON.stringify(getValue(next, key))}`).join(', ')}`);
553	    if (changed.some((key) => key.startsWith('history.'))) { this.applyHistoryConfig(); }
554	    this.emit({ event: 'configChanged', config: this.config });
555	    void this.runtime.sync();
556	    if (this.timer) void this.pollUsage();
557	    // A switch that was just turned on should act now, not in a minute.
558	    void this.automation.tick();
559	    return this.config;
560	  }
