562	  // --- sign-in with the vendor CLI ------------------------------------------------------------------------------
563	
564	  /** The command a client runs in a terminal to sign in for a profile, with a home that cannot touch the active login. */
565	  prepareSignIn(provider: AuthProvider): SignInPreparation {
566	    const settings = automationSettings(this.config, provider);
567	    const cli = resolveCli(settings.cliPath);
568	    if (!cli) { throw new Error(`${settings.cliPath} was not found. Check the ${provider} CLI path setting.`); }
569	    const home = loginHome(provider, settings.home);
570	    const file = stagedCredentialPath(provider, home);
571	    // A leftover from an earlier sign-in must not be mistaken for this one.
572	    fs.rmSync(file, { force: true });
573	    const env: Record<string, string> = {};
574	    for (const [key, value] of Object.entries(isolatedEnvironment(provider, home))) {
575	      if (typeof value === 'string') { env[key] = value; }
576	    }
577	    // The user is about to attend a browser sign-in; keep-alives and sweeps of this service wait until it is over,
578	    // so no check competes with it and no notification about another account interrupts it.
579	    this.automation.hold(provider, `a ${TITLES[provider]} sign-in is in progress`);
580	    return { cli, args: loginArgs(provider), cwd: home, env, file };
581	  }
582	
583	  /** Reads the login the vendor CLI wrote and stores it in the profile; the file is removed once it is taken. */
584	  async finishSignIn(provider: AuthProvider, id: string, allowOtherAccount: boolean): Promise<SignInResult> {
585	    const profile = this.store.profile(provider, id);
586	    if (!profile) { throw new Error('The profile no longer exists.'); }
587	    const settings = automationSettings(this.config, provider);
588	    const file = stagedCredentialPath(provider, loginHome(provider, settings.home));
589	    let credential: StoredCredential;
590	    try { credential = parseCredentialJson(provider, fs.readFileSync(file, 'utf8')); }
591	    catch { this.automation.resume(provider); throw new Error('The sign-in was not completed: the CLI wrote no login.'); }
592	    const identity = await this.store.identity(provider, credential);
593	    const otherAccount = (profile.accountId && identity.accountId && profile.accountId !== identity.accountId) ||
594	      (profile.email && identity.email && profile.email.toLowerCase() !== identity.email.toLowerCase());
595	    if (otherAccount && !allowOtherAccount) {
596	      return { status: 'otherAccount', identity,
597	        message: `You signed in as ${identity.email ?? identity.accountId}, but the profile “${profile.name}” holds ${profile.email ?? profile.accountId}.` };
598	    }
599	    const active = await this.automation.withPaused(() => this.store.replaceCredential(provider, id, credential));
600	    fs.rmSync(file, { force: true });
601	    this.automation.resume(provider);
602	    this.emit({ event: 'stateChanged', provider });
603	    // The login is saved either way; a busy check elsewhere only delays the usage reading.
604	    const result = await this.automation.credentialReplaced(provider, id).catch((error: unknown): KeepAliveNowResult =>
605	      ({ usage: undefined, usageError: error instanceof Error ? error.message : String(error) }));
606	    this.emit({ event: 'stateChanged', provider });
607	    const signedInAs = identity.email ? ` as ${identity.email}` : '';
608	    const usageNote = result.usage ? ' Usage statistics updated.' : result.usageError ? ` Usage could not be read yet: ${readableProblem(result.usageError)}` : '';
609	    return { status: 'replaced', active, identity, message: `${TITLES[provider]} profile “${profile.name}” signed in again${signedInAs}.${usageNote}` };
610	  }
611	
612	  cancelSignIn(provider: AuthProvider): void {
613	    const settings = automationSettings(this.config, provider);
614	    fs.rmSync(stagedCredentialPath(provider, loginHome(provider, settings.home)), { force: true });
615	    this.automation.resume(provider);
616	  }
617	
618	  // --- import and export ---------------------------------------------------------------------------------------
619	
620	  private planViews(plans: Array<ImportPlan<ProfileMetadata>>): ImportPlanView[] {
621	    return plans.map((plan) => ({
622	      provider: plan.entry.provider, id: plan.entry.id, name: plan.entry.name, email: plan.entry.email, kind: plan.kind,
623	      target: plan.target ? { id: plan.target.id, name: plan.target.name } : undefined,
624	      outcome: importOutcome(plan), suggested: plan.kind === 'new' || plan.kind === 'restore'
625	    }));
626	  }
627	
628	  private entriesParam(params: Record<string, unknown>): ExportedProfile[] {
629	    if (typeof params.text === 'string') { return parseProfileExport(params.text); }
630	    if (Array.isArray(params.entries)) { return parseProfileExport(JSON.stringify({ aiUsageProfiles: 1, profiles: params.entries })); }
631	    throw new Error('Nothing to import: pass the export text or its entries.');
632	  }
633	
634	  // --- the method dispatcher -----------------------------------------------------------------------------------
635	
636	  async handle(method: string, rawParams: unknown, clientId?: number): Promise<unknown> {
637	    const params = objectParams(rawParams);
638	    const paused = <T>(operation: () => Promise<T>) => this.automation.withPaused(operation);
639	    switch (method) {
640	      case 'service.info': return this.info();
641	      case 'runtime.staleCodex': return findStaleCodexProcesses(Number(params.switchedAt), Number(params.parentPid));
642	      case 'mcp.registration': {
643	        const provider = providerParam(params), launcher = mcpLauncher(this.options.home);
644	        return { launcher, ...mcpCli(provider, this.config[provider].cliPath), registration: readMcpRegistration(provider, launcher) };
645	      }
646	      case 'mcp.register':
647	      case 'mcp.unregister': {
648	        const provider = providerParam(params), resolved = mcpCli(provider, this.config[provider].cliPath);
649	        if (!resolved.cli) throw new Error(resolved.reason);
650	        return method === 'mcp.register' ? registerMcpServer(provider, resolved.cli, mcpLauncher(this.options.home)) : unregisterMcpServer(provider, resolved.cli);
651	      }
652	      case 'runtime.status': return { codexProxyActive: this.runtime.proxy.active };
653	      case 'bridge.ensure': return this.runtime.bridge.ensure();
654	      case 'bridge.connection': return this.runtime.bridge.connection();
655	      case 'bridge.sync': await this.runtime.bridge.syncSettings(); return { ok: true };
656	      case 'usage.context': {
657	        if (clientId === undefined) throw new Error('Usage context needs a connected client.');
658	        const accounts = Array.isArray(params.accounts) ? params.accounts.filter((a): a is { login: string; token: string } =>
659	          !!a && typeof a.login === 'string' && typeof a.token === 'string').slice(0, 20) : [];
660	        const workspaceOwners = Array.isArray(params.workspaceOwners) ? params.workspaceOwners.filter((o): o is string => typeof o === 'string').slice(0, 100) : [];
661	        this.usageContexts.set(clientId, { accounts, workspaceOwners });
662	        return { ok: true };
663	      }
664	      case 'usage.live': {
665	        const provider = params.provider;
666	        if (provider !== 'claude' && provider !== 'codex' && provider !== 'copilot') throw new Error('Unknown usage provider.');
667	        return this.liveUsage(provider, params.force === true, clientId);
668	      }
669	      case 'usage.sessionTokens': {
670	        const provider = providerParam(params);
671	        return readCurrentSessionTokens(provider, this.foldersByClient.get(clientId ?? -1) ?? []) ?? null;
672	      }
673	      case 'rotation.diagnostics': return this.automation.diagnostics(providerParam(params));
674	      case 'snapshot': return this.snapshot();
675	      case 'profiles.list': return this.providerView(providerParam(params));
676	      case 'session.folders': {
677	        if (clientId === undefined) { throw new Error('Only a connected client can declare project folders.'); }
678	        this.declareFolders(clientId, Array.isArray(params.folders) ? params.folders.filter((folder): folder is string => typeof folder === 'string') : []);
679	        return { ok: true };
680	      }
681	      case 'profiles.activate': {
682	        const provider = providerParam(params);
683	        const profile = this.resolveParam(provider, params);
684	        const outcome = await paused(() => this.automation.withAccountLock(provider, () => this.activate(provider, profile.id, false), { waitMs: MANUAL_CHECK_WAIT_MS }));
685	        const result: ActivationResult = { profile: { id: outcome.profile.id, name: outcome.profile.name, email: outcome.profile.email },
686	          verification: outcome.verification, level: outcome.level, message: outcome.message, accountChanged: outcome.accountChanged };
687	        void this.automation.tick();
688	        return result;
689	      }
690	      case 'profiles.saveNative': {
691	        const provider = providerParam(params);
692	        const outcome = await paused(() => this.store.saveNative(provider, {
693	          name: typeof params.name === 'string' ? params.name : undefined,
694	          id: typeof params.id === 'string' ? params.id : undefined,
695	          allowDuplicate: params.allowDuplicate === true,
696	          folder: typeof params.folder === 'string' && params.folder ? params.folder : undefined
697	        }));
698	        if (outcome.status !== 'duplicate') { this.emit({ event: 'stateChanged', provider }); void this.automation.tick(); }
699	        return outcome as SaveNativeResult;
700	      }
701	      case 'profiles.importCredential': {
702	        const provider = providerParam(params);
703	        const outcome = await paused(() => this.store.importCredential(provider, stringParam(params, 'name'), params.credential, params.allowDuplicate === true,
704	          typeof params.folder === 'string' && params.folder ? params.folder : undefined));
705	        if (outcome.status !== 'duplicate') { this.emit({ event: 'stateChanged', provider }); void this.automation.tick(); }
706	        return outcome as SaveNativeResult;
707	      }
708	      case 'profiles.rename': {
709	        const provider = providerParam(params);
710	        const profile = this.resolveParam(provider, params);
711	        const renamed = await paused(async () => this.store.rename(provider, profile.id, stringParam(params, 'name')));
712	        this.emit({ event: 'stateChanged', provider });
713	        return renamed;
714	      }
715	      case 'profiles.reorder': {
716	        const provider = providerParam(params);
717	        const profile = this.resolveParam(provider, params);
718	        if (params.step !== -1 && params.step !== 1) { throw new Error('Step must be -1 or 1.'); }
719	        const profiles = await paused(async () => this.store.reorder(provider, profile.id, params.step as -1 | 1));
720	        this.emit({ event: 'stateChanged', provider });
721	        return profiles;
722	      }
723	      case 'profiles.delete': {
724	        const provider = providerParam(params);
725	        const profile = this.resolveParam(provider, params);
726	        const deleted = await paused(async () => this.store.delete(provider, profile.id));
727	        this.emit({ event: 'stateChanged', provider });
728	        return deleted;
729	      }
730	      case 'profiles.export': {
731	        const selection = Array.isArray(params.selection)
732	          ? params.selection.map((entry) => ({ provider: providerParam(objectParams(entry)), id: stringParam(objectParams(entry), 'id') })) : undefined;
733	        const { entries, missing } = this.store.exportEntries(selection);
734	        const result: ExportResult = { entries, missing, text: serializeProfileExport(entries) };
735	        this.log(`exported ${entries.length} authentication profiles`);
736	        return result;
737	      }
738	      case 'profiles.planImport': return this.planViews(this.store.planImport(this.entriesParam(params)));
739	      case 'profiles.applyImport': {
740	        const plans = this.store.planImport(this.entriesParam(params));
741	        const chosen = Array.isArray(params.chosen)
742	          ? plans.filter((plan) => (params.chosen as unknown[]).some((wanted) => {
743	            const entry = objectParams(wanted);
744	            return entry.provider === plan.entry.provider && entry.id === plan.entry.id;
745	          }))
746	          : plans.filter((plan) => plan.kind === 'new' || plan.kind === 'restore');
747	        if (!chosen.length) { return { imported: 0, counts: { new: 0, restore: 0, replace: 0, same: 0 }, summary: 'nothing to import' } satisfies ImportSummary; }
748	        const outcome = await paused(() => this.store.applyImport(chosen));
749	        for (const provider of PROVIDERS) { this.emit({ event: 'stateChanged', provider }); }
750	        void this.automation.tick();
751	        return outcome satisfies ImportSummary;
752	      }
753	      case 'profiles.signIn.prepare': return this.prepareSignIn(providerParam(params));
754	      case 'profiles.signIn.finish': {
755	        const provider = providerParam(params);
756	        return this.finishSignIn(provider, this.resolveParam(provider, params).id, params.allowOtherAccount === true);
757	      }
758	      case 'profiles.signIn.cancel': this.cancelSignIn(providerParam(params)); return { ok: true };
759	      case 'automation.keepAliveNow': {
760	        const provider = providerParam(params);
761	        const profile = this.resolveParam(provider, params);
762	        const wait = this.waitFor(provider, params);
763	        try {
764	          const result = await this.automation.sendKeepAliveNow(provider, profile.id, { callerReports: params.callerReports === true, wait });
765	          this.emit({ event: 'stateChanged', provider });
766	          return serializeKeepAlive(result);
767	        } finally { this.releaseWait(wait); }
768	      }
769	      case 'automation.keepAliveAll': {
770	        const provider = providerParam(params);
771	        const saved = this.store.profiles(provider);
772	        const profiles = Array.isArray(params.ids)
773	          ? (params.ids as unknown[]).flatMap((id) => { const profile = saved.find((candidate) => candidate.id === id); return profile ? [profile] : []; })
774	          : saved;
775	        const wait = this.waitFor(provider, params);
776	        try {
777	          const result = await this.keepAliveAll(provider, profiles, wait);
778	          this.emit({ event: 'stateChanged', provider });
779	          return result;
780	        } finally { this.releaseWait(wait); }
781	      }
782	      case 'automation.cancel': {
783	        const token = stringParam(params, 'token');
784	        this.cancels.get(token)?.abort();
785	        return { ok: true };
786	      }
787	      case 'automation.rotateNow': {
788	        const provider = providerParam(params);
789	        const wait = this.waitFor(provider, params);
790	        try {
791	          const outcome = await this.automation.rotateNow(provider, wait);
792	          this.emit({ event: 'stateChanged', provider });
793	          return { ...outcome, activeProfileId: this.store.activeProfileId(provider), activeProfileName: this.store.activeProfileName(provider) };
794	        } finally { this.releaseWait(wait); }
795	      }
796	      case 'automation.tick': await this.tick(); return { ok: true };
797	      case 'usage.read': {
798	        const provider = providerParam(params);
799	        const profile = this.resolveParam(provider, params);
800	        const result = await this.automation.readUsageNow(provider, profile.id);
801	        this.emit({ event: 'stateChanged', provider });
802	        return { profile: { id: profile.id, name: profile.name, email: profile.email }, ...serializeKeepAlive(result) } satisfies UsageReadResult;
803	      }
804	      case 'usage.observe':
805	      case 'usage.hintLimit': throw new Error('Usage is collected by the service; use usage.live or usage.read.');
806	      case 'history.info': return this.historyInfo();
807	      case 'history.summary': return this.historySummary(typeof params.days === 'number' && params.days > 0 ? params.days : undefined);
808	      case 'history.export': {
809	        const kind = params.kind;
810	        if (kind !== 'readings' && kind !== 'events' && kind !== 'jsonl') { throw new Error('Choose what to export: readings, events or jsonl.'); }
811	        return this.historyExport(kind);
812	      }
813	      case 'config.get': return this.config;
814	      case 'config.set': return this.setConfig(objectParams(params.values));
815	      default: throw new Error(`Unknown method ${method}.`);
816	    }
817	  }
818	
819	  /** `id`, or a `ref` (name, number or id), must name a saved profile. */
820	  private resolveParam(provider: AuthProvider, params: Record<string, unknown>): ProfileMetadata {
821	    if (typeof params.id === 'string' && params.id) {
822	      const profile = this.store.profile(provider, params.id);
823	      if (!profile) { throw new Error('The profile no longer exists.'); }
824	      return profile;
825	    }
826	    const reference = stringParam(params, 'ref');
827	    const profile = this.store.resolve(provider, reference);
828	    if (!profile) { throw new Error(`No ${TITLES[provider]} profile matches "${reference}". Run "ai-usage list ${provider}" to see them.`); }
829	    return profile;
830	  }
831	}
832	
833	function getValue(config: ServiceConfig, dotted: string): unknown {
834	  let current: unknown = config;
835	  for (const key of dotted.split('.')) {
836	    current = typeof current === 'object' && current !== null ? (current as Record<string, unknown>)[key] : undefined;
837	  }
838	  return current;
839	}
