import type { AuthProvider } from './authFiles';
import type { ActivationVerification } from './profileStore';
import type { ServiceConfig } from './configStore';
import type { ExportedProfile, ImportKind } from './profileTransfer';
import type { KeepAliveNowResult } from './accountAutomation';
import type { ProviderId } from './live';

/**
 * What travels between the service and its clients (the VS Code extension and the `ai-usage` command): plain JSON
 * with ISO dates. Requests are `{ id, method, params }`, answers `{ id, result }` or `{ id, error }`, and the
 * service pushes `{ event, data }` messages to subscribed clients.
 */

export type SerializedWindow = { label: string; usedPercent: number; resetsAt?: string };
export type SerializedUsage = { provider: ProviderId; title: string; plan?: string; subtitle?: string; windows: SerializedWindow[];
  resetCredits?: { availableCount: number; earliestExpiresAt?: number; totalCount?: number }; details?: string[]; fetchedAt: string };

export type AccountProblemView = {
  /** Which check failed. */
  check: 'keepAlive' | 'usage';
  raw: string;
  /** A few words, such as "Insufficient credits"; the vendor's own text when not recognized. */
  label: string;
  advice?: string;
  known: boolean;
};

export type ProfileView = {
  id: string;
  name: string;
  email?: string;
  accountId?: string;
  createdAt: string;
  updatedAt: string;
  active: boolean;
  /** 1-based position in the saved list. */
  number: number;
  usage?: SerializedUsage;
  checkedAt?: string;
  lastKeepAliveAt?: string;
  problems: AccountProblemView[];
  /** Nothing left in any counted window (`readOnly`), or only a model-scoped weekly window is used up (`dimmed`). */
  limit: { readOnly: boolean; dimmed: boolean };
  /** The login error of the last check, when it was one; such a profile is re-checked instead of activated. */
  loginProblem?: string;
  /** Whether the service holds the profile's login at all. */
  hasCredential: boolean;
  /** The project folder a project profile lives in; a private profile has none. */
  folder?: string;
};

export type ProviderView = {
  provider: AuthProvider;
  title: string;
  profiles: ProfileView[];
  activeProfileId?: string;
  /** 1-based position of the active profile; absent when the native login belongs to no saved profile. */
  activeNumber?: number;
  /** The native login was not saved as a profile. */
  nativeUnsaved: boolean;
  /** The active account is being checked right now (its tokens may be refreshed meanwhile). */
  checkingActive: boolean;
  keepAlive: boolean;
  autoRotate: boolean;
  strategySummary: string;
  /** Where a new profile may be kept: privately, and in which of the declared project folders. */
  scopes: { privateEnabled: boolean; projectEnabled: boolean; folders: string[] };
};

export type ServiceInfo = {
  version: string;
  pid: number;
  startedAt: string;
  home: string;
  node: string;
  socket: string;
  clients: number;
  /** Where the private profiles are: `service` (profiles.json in the home) or `vscode` (a VS Code window's storage). */
  profileStore?: 'service' | 'vscode';
};

export type Snapshot = {
  service: ServiceInfo;
  providers: Record<AuthProvider, ProviderView>;
  config: ServiceConfig;
};

export type ActivationResult = {
  profile: { id: string; name: string; email?: string };
  verification?: ActivationVerification;
  /** `info` for a clean switch, `warning` when unconfirmed, `error` when the vendor reports another login. */
  level: 'info' | 'warning' | 'error';
  message: string;
  /** Whether running processes now see another account than before. */
  accountChanged: boolean;
};

export type SaveNativeResult =
  | { status: 'saved' | 'updated'; profile: { id: string; name: string; email?: string } }
  /** The login is already saved as `twin`; call again with `allowDuplicate` to save a copy anyway. */
  | { status: 'duplicate'; twin: { id: string; name: string }; warning: string };

export type ImportPlanView = {
  provider: AuthProvider;
  id: string;
  name: string;
  email?: string;
  kind: ImportKind;
  target?: { id: string; name: string };
  /** Short description of what importing the entry does, for a list. */
  outcome: string;
  /** Whether a plain import selects it: new profiles and restored logins. */
  suggested: boolean;
};

export type ImportSummary = { imported: number; counts: Record<ImportKind, number>; summary: string };

export type ExportResult = { entries: ExportedProfile[]; missing: string[]; text: string };

export type SignInPreparation = {
  cli: string;
  args: string[];
  cwd: string;
  env: Record<string, string>;
  /** Where the vendor CLI writes the login inside the isolated home. */
  file: string;
};

export type SignInResult =
  | { status: 'replaced'; active: boolean; identity: { email?: string; accountId?: string }; message: string }
  /** The sign-in belongs to another account than the profile holds; call again with `allowOtherAccount`. */
  | { status: 'otherAccount'; identity: { email?: string; accountId?: string }; message: string };

export type ServiceEvent =
  | { event: 'activated'; provider: AuthProvider; id: string; name: string; email?: string; automatic: boolean; accountChanged: boolean; level: 'info' | 'warning' | 'error'; message: string }
  | { event: 'accountProblem'; provider: AuthProvider; id: string; name: string; email?: string; reason: string; readable: string; revoked: boolean }
  | { event: 'noCandidate'; provider: AuthProvider; detail: string }
  | { event: 'notice'; level: 'info' | 'warning' | 'error'; message: string; provider?: AuthProvider }
  | { event: 'usageChanged'; provider: ProviderId }
  | { event: 'stateChanged'; provider?: AuthProvider }
  | { event: 'configChanged'; config: ServiceConfig }
  /** A check requested with `token` waits for a running sweep of the service to finish. */
  | { event: 'waiting'; provider: AuthProvider; token?: string }
  /** A keep-alive sweep requested with `token` is about to check account `index` of `total`. */
  | { event: 'keepAliveProgress'; provider: AuthProvider; token?: string; index: number; total: number; id: string; name: string }
  | { event: 'log'; line: string };

export type EventName = ServiceEvent['event'];

export type HelloParams = { token: string; client: string; version?: string; subscribe?: EventName[] | 'all';
  /** Project folders open at the client, whose profile files the service lists while the client is connected. */
  folders?: string[] };
export type HelloResult = { ok: true; service: ServiceInfo };

export type KeepAliveResult = { usage?: SerializedUsage; keepAliveError?: string; usageError?: string };

/** What a check requested by hand does about a sweep that is running: wait for it, and stop on `automation.cancel` with the token. */
export type CheckWait = { waitMs?: number; token?: string };

/** `automation.keepAliveAll`: one keep-alive sweep over several accounts under one lock. */
export type KeepAliveAllResult = {
  results: Array<{ id: string; name: string; error?: string } & KeepAliveResult>;
  /** Accounts the sweep got to; the rest were not sent. */
  done: number;
  total: number;
  /** Why the sweep stopped early, when it did not finish or start: a sign-in, or a check still running after the wait. */
  blocked?: string;
  cancelled: boolean;
};

/** `history.info`: where the usage history is and how much of it there is. */
export type HistoryInfo = { enabled: boolean; location: string; retentionDays: number; files: string[]; oldestAt?: string };

/** `history.summary`: the period summarized as a Markdown document, with the figures behind it. */
export type HistorySummaryResult = { markdown: string; since: string; until: string; label: string; summary: unknown };

export type HistoryExportKind = 'readings' | 'events' | 'jsonl';

/** `usage.read`: a fresh reading of one profile, without a keep-alive prompt. */
export type UsageReadResult = KeepAliveResult & { profile: { id: string; name: string; email?: string } };

export function serializeKeepAlive(result: KeepAliveNowResult): KeepAliveResult {
  return {
    usage: result.usage ? { ...result.usage, fetchedAt: result.usage.fetchedAt.toISOString(),
      windows: result.usage.windows.map((window) => ({ label: window.label, usedPercent: window.usedPercent, resetsAt: window.resetsAt?.toISOString() })) } : undefined,
    keepAliveError: result.keepAliveError,
    usageError: result.usageError
  };
}
import { EventEmitter } from 'events';
import * as fs from 'fs';
import * as net from 'net';

/**
 * Newline-delimited JSON over a local socket. A client's first message must be `hello` with the shared token;
 * until then the connection answers nothing but an error and is closed. No `vscode` imports: the extension and
 * the command line share this module.
 */

export type RpcRequest = { id: number; method: string; params?: unknown };
export type RpcResponse = { id: number; result?: unknown; error?: { message: string; code?: string } };
/** A pushed message: the event name and its fields, flat. */
export type RpcEvent = { event: string } & Record<string, unknown>;

export class RpcError extends Error {
  constructor(message: string, readonly code?: string) { super(message); }
}

/** Server-side view of one client. */
export type RpcConnection = {
  readonly id: number;
  client: string;
  version?: string;
  subscriptions: Set<string> | 'all';
  send(event: RpcEvent): void;
  close(): void;
};

export type RpcServerOptions = {
  socketPath: string;
  token: string;
  /** Handles a method after the hello; `hello` itself is handled here. */
  handle: (method: string, params: unknown, connection: RpcConnection) => Promise<unknown>;
  /** Called with the hello params once a client authenticated; may throw to refuse it. */
  onHello?: (connection: RpcConnection, params: Record<string, unknown>) => unknown;
  onDisconnect?: (connection: RpcConnection) => void;
  log?: (message: string) => void;
};

const MAX_LINE_BYTES = 8 * 1024 * 1024;

/** Splits a socket's bytes into JSON lines; an oversized or malformed line closes the connection. */
export function lineReader(socket: net.Socket, onLine: (line: string) => void, onError: (error: Error) => void): void {
  let buffer = '';
  socket.setEncoding('utf8');
  socket.on('data', (chunk: string) => {
    buffer += chunk;
    if (buffer.length > MAX_LINE_BYTES) { onError(new Error('message too large')); return; }
    let newline = buffer.indexOf('\n');
    while (newline >= 0) {
      const line = buffer.slice(0, newline).trim();
      buffer = buffer.slice(newline + 1);
      newline = buffer.indexOf('\n');
      if (line) { onLine(line); }
    }
  });
}

export class RpcServer {
  private readonly server: net.Server;
  private readonly connections = new Map<number, RpcConnection>();
  private nextId = 1;

  constructor(private readonly options: RpcServerOptions) {
    this.server = net.createServer((socket) => this.accept(socket));
  }

  get clientCount(): number { return this.connections.size; }

  /** Lists authenticated clients. */
  clients(): RpcConnection[] { return [...this.connections.values()]; }

  async listen(): Promise<void> {
    await removeStaleSocket(this.options.socketPath);
    await new Promise<void>((resolve, reject) => {
      this.server.once('error', reject);
      this.server.listen(this.options.socketPath, () => { this.server.off('error', reject); resolve(); });
    });
    if (process.platform !== 'win32') {
      try { fs.chmodSync(this.options.socketPath, 0o600); } catch { /* Best effort; the directory is 0700. */ }
    }
  }

  broadcast(event: RpcEvent): void {
    for (const connection of this.connections.values()) {
      if (connection.subscriptions === 'all' || connection.subscriptions.has(event.event)) { connection.send(event); }
    }
  }

  async close(): Promise<void> {
    for (const connection of this.connections.values()) { connection.close(); }
    await new Promise<void>((resolve) => this.server.close(() => resolve()));
    if (process.platform !== 'win32') {
      try { fs.unlinkSync(this.options.socketPath); } catch { /* Already gone. */ }
    }
  }

  private accept(socket: net.Socket): void {
    const id = this.nextId++;
    let authenticated = false;
    const write = (message: RpcResponse | RpcEvent) => {
      if (!socket.destroyed) { socket.write(`${JSON.stringify(message)}\n`); }
    };
    const connection: RpcConnection = {
      id, client: 'unknown', subscriptions: new Set(),
      send: (event) => write(event),
      close: () => socket.destroy()
    };
    const fail = (message: string, id = 0) => { write({ id, error: { message } }); socket.end(); };
    socket.on('error', () => { /* A client that vanished; close handles it. */ });
    socket.on('close', () => {
      if (authenticated) {
        this.connections.delete(id);
        this.options.onDisconnect?.(connection);
      }
    });
    lineReader(socket, (line) => {
      let request: RpcRequest;
      try { request = JSON.parse(line) as RpcRequest; } catch { fail('malformed request'); return; }
      if (typeof request.id !== 'number' || typeof request.method !== 'string') { fail('malformed request'); return; }
      if (!authenticated) {
        const params = (typeof request.params === 'object' && request.params !== null ? request.params : {}) as Record<string, unknown>;
        if (request.method !== 'hello' || params.token !== this.options.token) {
          this.options.log?.(`rpc: refused a connection that did not start with a valid hello`);
          fail('unauthorized: the first message must be hello with the service token', request.id);
          return;
        }
        authenticated = true;
        connection.client = typeof params.client === 'string' ? params.client : 'unknown';
        connection.version = typeof params.version === 'string' ? params.version : undefined;
        connection.subscriptions = params.subscribe === 'all' ? 'all' : new Set(Array.isArray(params.subscribe) ? params.subscribe.map(String) : []);
        this.connections.set(id, connection);
        Promise.resolve().then(() => this.options.onHello?.(connection, params)).then(
          (result) => write({ id: request.id, result: result ?? { ok: true } }),
          (error) => { write({ id: request.id, error: { message: error instanceof Error ? error.message : String(error) } }); socket.end(); });
        return;
      }
      this.options.handle(request.method, request.params, connection).then(
        (result) => write({ id: request.id, result: result ?? null }),
        (error) => write({ id: request.id, error: { message: error instanceof Error ? error.message : String(error), code: error instanceof RpcError ? error.code : undefined } }));
    }, (error) => fail(error.message));
  }
}

/** A leftover Unix socket file with nobody listening keeps a new daemon from binding it. */
async function removeStaleSocket(socketPath: string): Promise<void> {
  if (process.platform === 'win32' || !fs.existsSync(socketPath)) { return; }
  const alive = await new Promise<boolean>((resolve) => {
    const probe = net.connect(socketPath);
    probe.once('connect', () => { probe.destroy(); resolve(true); });
    probe.once('error', () => resolve(false));
  });
  if (alive) { throw new Error(`another service is already listening on ${socketPath}`); }
  fs.unlinkSync(socketPath);
}

export type RpcClientOptions = {
  socketPath: string;
  token: string;
  client: string;
  version?: string;
  subscribe?: string[] | 'all';
  /** Project folders open at the client. */
  folders?: string[];
  /** Connect and hello timeout. */
  timeoutMs?: number;
};

/** Client side: one socket, sequential ids, typed events. Emits `event` with each pushed message and `close`. */
export class RpcClient extends EventEmitter {
  private readonly pending = new Map<number, { resolve: (value: unknown) => void; reject: (error: Error) => void; timer?: NodeJS.Timeout }>();
  private nextId = 1;
  private closed = false;

  private constructor(private readonly socket: net.Socket) {
    super();
    lineReader(socket, (line) => this.receive(line), (error) => this.socket.destroy(error));
    socket.on('close', () => {
      this.closed = true;
      for (const entry of this.pending.values()) { clearTimeout(entry.timer); entry.reject(new RpcError('the service connection was closed', 'closed')); }
      this.pending.clear();
      this.emit('close');
    });
    socket.on('error', (error) => { this.emit('error', error); });
  }

  static connect(options: RpcClientOptions): Promise<{ client: RpcClient; hello: unknown }> {
    const timeoutMs = options.timeoutMs ?? 5_000;
    return new Promise((resolve, reject) => {
      const socket = net.connect(options.socketPath);
      const timer = setTimeout(() => { socket.destroy(); reject(new RpcError('timed out connecting to the service', 'timeout')); }, timeoutMs);
      socket.once('error', (error) => { clearTimeout(timer); reject(error); });
      socket.once('connect', () => {
        const client = new RpcClient(socket);
        // Nothing else may be sent before the hello is answered.
        client.call('hello', { token: options.token, client: options.client, version: options.version, subscribe: options.subscribe ?? [], folders: options.folders }, timeoutMs).then(
          (hello) => { clearTimeout(timer); resolve({ client, hello }); },
          (error) => { clearTimeout(timer); socket.destroy(); reject(error); });
      });
    });
  }

  get isClosed(): boolean { return this.closed; }

  call(method: string, params?: unknown, timeoutMs = 10 * 60_000): Promise<unknown> {
    if (this.closed) { return Promise.reject(new RpcError('the service connection is closed', 'closed')); }
    const id = this.nextId++;
    return new Promise((resolve, reject) => {
      const timer = setTimeout(() => { this.pending.delete(id); reject(new RpcError(`the service did not answer ${method} in time`, 'timeout')); }, timeoutMs);
      this.pending.set(id, { resolve, reject, timer });
      this.socket.write(`${JSON.stringify({ id, method, params } satisfies RpcRequest)}\n`);
    });
  }

  close(): void {
    this.closed = true;
    this.socket.end();
    this.socket.destroy();
  }

  private receive(line: string): void {
    let message: RpcResponse & RpcEvent;
    try { message = JSON.parse(line); } catch { return; }
    if (typeof message.event === 'string') { this.emit('event', message); return; }
    const entry = this.pending.get(message.id);
    if (!entry) { return; }
    this.pending.delete(message.id);
    clearTimeout(entry.timer);
    if (message.error) { entry.reject(new RpcError(message.error.message, message.error.code)); }
    else { entry.resolve(message.result); }
  }
}

