      try {
        if (Date.now() - fs.statSync(guard).mtimeMs > RECLAIM_GUARD_STALE_MS) { fs.rmdirSync(guard); continue; }
      } catch { continue; }
      return false;
    }
    try { work(); } finally { try { fs.rmdirSync(guard); } catch { /* Already gone. */ } }
