    if (!existing?.record || existing.record.pid === process.pid || processAlive(existing.record.pid)) { return undefined; }
    let taken = false;
    withReclaimGuard(file, () => {
      // Re-check under the guard: another reclaimer may have replaced the stale lock meanwhile.
      const again = readLock(file);
      if (again && again.text !== existing.text) { return; }
      if (again) { try { fs.unlinkSync(file); } catch { return; } }
      taken = createLock(file, record);
    });
    if (!taken) { return undefined; }
  }
  const state: LeaseState = { held: true, listeners: [] };
  const owned = () => readLock(file)?.record?.instanceId === record.instanceId;
  const timer = setInterval(() => { if (!owned()) { clearInterval(timer); lost(state); } }, FILE_LEASE_CHECK_MS);
  timer.unref?.();
  const lease = makeLease('file', home, record.instanceId, state, () => {
    clearInterval(timer);
    try { if (owned()) { fs.unlinkSync(file); } } catch { /* Already removed. */ }
  });
  const assertHeld = lease.assertHeld;
  // A file lease can be lost without an event (someone deleted the lock); check the file itself before a write.
  return { ...lease, assertHeld: () => { assertHeld(); if (!owned()) { lost(state); throw new LeaseLostError(home); } } };
}

