  const lease = makeLease('file', home, record.instanceId, state, () => {
    clearInterval(timer);
    try { if (owned()) { fs.unlinkSync(file); } } catch { /* Already removed. */ }
  });
  const assertHeld = lease.assertHeld;
  // A file lease can be lost without an event (someone deleted the lock); check the file itself before a write.
  return { ...lease, assertHeld: () => { assertHeld(); if (!owned()) { lost(state); throw new LeaseLostError(home); } } };
}

