  if (WORKSPACE_KEYS.has(dotted)) { return 'workspace'; }
  if (PRESENTATION_KEYS.has(dotted) || dotted.startsWith('statusBar.') || dotted.startsWith('chatChips.')) { return 'presentation'; }
  return 'engine';
