/**
 * Whether some process holds the home's lease, without taking it (taking it, even briefly, could make a host that is
 * starting right now fail). The OS endpoint accepts connections only while held; a lock file counts while its pid lives.
 */
export async function leaseHeld(home: string, options: { kind?: LeaseKind } = {}): Promise<boolean> {
  const kind = options.kind ?? defaultLeaseKind();
  const real = canonicalHome(home);
  if (kind === 'file') {
    const existing = readLock(engineLockFile(real));
    if (!existing) { return false; }
    return !existing.record || processAlive(existing.record.pid);
  }
  return new Promise((resolve) => {
    const socket = net.connect(leaseEndpoint(real));
    const done = (held: boolean) => { socket.destroy(); resolve(held); };
    socket.setTimeout(1_000, () => done(true));
    socket.once('connect', () => done(true));
    socket.once('error', (error: NodeJS.ErrnoException) => done(!(error.code === 'ECONNREFUSED' || error.code === 'ENOENT')));
  });
}
