export const MCP_SERVER_NAME = 'ai-usage';
const CLI_TIMEOUT_MS = 60_000;

/** What a CLI's configuration holds for the server. */
export type McpRegistration = {
  /** A server of that name is configured, whatever it runs. */
  registered: boolean;
  command?: string;
  args?: string[];
  env?: Record<string, string>;
  /** The configured command is this launcher with `mcp`, so the CLI runs the installed service. */
  current: boolean;
};

/** The file each CLI keeps its servers in: Claude Code's `.claude.json` (user scope) and Codex's `config.toml`. */
export function mcpConfigFile(provider: AuthProvider): string {
  return provider === 'claude' ? claudeAccountFile() : codexConfigPath(codexHomeDir());
}

/** The launcher the CLI is told to run; it sets the service home itself, so no `--home` is needed. */
export function mcpLauncher(home: string): string {
  return launcherPath(home);
}

/** Installed launcher or the bundled stdio adapter; both only connect to an existing engine. */
export type McpCommand = { command: string; args: string[]; env?: Record<string, string> };
export function mcpCommand(home: string): McpCommand {
  const launcher = mcpLauncher(home);
  if (fs.existsSync(launcher)) return { command: launcher, args: ['mcp'] };
  return { command: process.execPath, args: [path.resolve(__dirname, '..', 'bin', 'ai-usage.js'), 'mcp', '--home', home],
    ...(process.versions.electron ? { env: { ELECTRON_RUN_AS_NODE: '1' } } : {}) };
}
function commandOf(value: string | McpCommand): McpCommand {
  return typeof value === 'string' ? { command: value, args: ['mcp'] } : value;
}

/** The CLI to drive: the configured path resolved as the keep-alive resolves it, or why there is none. */
export function mcpCli(provider: AuthProvider, configured: string | undefined): { cli?: string; reason?: string } {
  const command = configured?.trim() || provider;
  const cli = resolveCli(command);
  return cli ? { cli } : { reason: `${command} was not found. Check the ${provider === 'claude' ? 'Claude' : 'Codex'} CLI path setting.` };
const fs = require('node:fs');
const path = require('node:path');

exports.hostOptions = (home, mode) => ({
  home, mode, embedded: mode === 'embedded', version: '1.0.10',
  seedConfig: { 'bridge.autoStart': false, 'codex.autoReset.enabled': false, 'claude.api.minIntervalSeconds': 0,
    'claude.keepAlive.enabled': false, 'codex.keepAlive.enabled': false,
    'claude.autoRotate.enabled': false, 'codex.autoRotate.enabled': false },
  engineOptions: {
    // All provider reads in this genuine socket host use local synthetic data.
    fetchUsage: async (provider, context) => {
      const state = JSON.parse(fs.readFileSync(path.join(home, 'fixture.json'), 'utf8'));
      fs.appendFileSync(path.join(home, 'reads.jsonl'), JSON.stringify({ provider, owners: context.workspaceOwners || [] }) + '\n');
      if (state.delayMs) await new Promise(resolve => setTimeout(resolve, state.delayMs));
      if (state.kind === 'unavailable') return { kind: 'unavailable', provider, reason: 'No synthetic usage yet.' };
      if (state.kind === 'error') return { kind: 'error', provider, title: provider, message: 'Synthetic provider unavailable', transient: true };
      return { kind: 'ok', usage: { provider, title: provider, fetchedAt: new Date(state.now - (state.ageMs || 0)), windows: [
        { label: '5h', usedPercent: 37, resetsAt: new Date(state.now + 3_600_000) },
        { label: '7d', usedPercent: 56, resetsAt: new Date(state.now + 7 * 86_400_000) },
        ...(provider === 'claude' ? [{ label: '7d Sonnet', usedPercent: 100, resetsAt: new Date(state.now + 7 * 86_400_000) }] : [])
      ] } };
    },
    identityOf: async (provider, credential) => ({ accountId: provider + '-fixture', email: provider + '@example.test' }),
    probe: async () => { throw new Error('The parity fixture must not probe provider accounts.'); },
    verifyCodex: async () => ({ status: 'match', detail: 'Synthetic verification' }),
    syncClaudeMetadata: async () => ({ status: 'match', detail: 'Synthetic metadata' })
  }
});
      const force = setTimeout(() => child.kill('SIGKILL'), 3_000);
      const timeout = setTimeout(() => { cleanup(); reject(new Error('The previous CLI bridge did not exit; refusing to start another.')); }, 6_000);
      const cleanup = () => { clearTimeout(force); clearTimeout(timeout); child.off('close', closed); };
      const closed = () => { cleanup(); if (this.child === child) this.child = undefined; resolve(); };
      child.once('close', closed);
      child.kill('SIGTERM');
    });
  }
  dispose(): Promise<void> {
    this.disposed = true;
    if (!this.stopping) this.stopping = (async () => {
      await this.stopChild();
      await this.starting?.catch(() => undefined);
      await this.stopChild();
    })();
    return this.stopping;
  }
}
